from pathlib import Path


def rep(path, old, new, label):
    p = Path(path)
    s = p.read_text(encoding='utf-8')
    n = s.count(old)
    if n != 1:
        raise RuntimeError(f'{label}: {n} matches')
    p.write_text(s.replace(old, new, 1), encoding='utf-8')


rep('PianoFromAbove/GameState.h',
    '''    long long m_llMaxNoteLen = 0;       // longest note, microseconds\n    long long m_llMaxNoteLenTicks = 0;  // longest note, ticks (tick mode)\n    bool m_bImageBufferNeedsInvalidate = true; // defer until renderer is attached''',
    '''    long long m_llMaxNoteLen = 0;       // longest note, microseconds\n    long long m_llMaxNoteLenTicks = 0;  // longest note, ticks (tick mode)\n    vector<long long> m_vImageBufferMaxEndTime;\n    vector<long long> m_vImageBufferMaxEndTick;\n    vector<long long> m_vImageBufferPrefixEndTime;\n    vector<long long> m_vImageBufferPrefixEndTick;\n    bool m_bImageBufferNeedsInvalidate = true; // defer until renderer is attached''',
    'GameState huge index members')

p = Path('PianoFromAbove/GameState.cpp')
s = p.read_text(encoding='utf-8')
a = s.index('template <typename BuildFn>\nstatic void ImageBufferCollectHugeLocal(')
b = s.index('\nstatic size_t CountImageBufferPrewarmCached(', a)
new_helper = '''static constexpr size_t ImageBufferHugeBlockEvents = 4096;\n\ntemplate <typename BuildFn>\nstatic void ImageBufferCollectHugeIndexed(\n    const std::vector<MIDIChannelEvent>& events,\n    MIDI& midi,\n    std::vector<NoteData>& out,\n    long long chunk,\n    long long timeSpan,\n    long long corruptionMargin,\n    bool tickMode,\n    const std::vector<long long>& maxEndTime,\n    const std::vector<long long>& maxEndTick,\n    const std::vector<long long>& prefixEndTime,\n    const std::vector<long long>& prefixEndTick,\n    BuildFn&& buildNote)\n{\n    out.clear();\n    if (events.empty() || timeSpan <= 0)\n        return;\n\n    const long long chunkStart = chunk * timeSpan;\n    const long long chunkEnd = ImageBufferOverlapSaturatingAdd(chunkStart, timeSpan);\n    const long long hi = ImageBufferOverlapSaturatingAdd(chunkEnd, corruptionMargin);\n    const long long oldestUsefulEnd = ImageBufferOverlapSaturatingAdd(\n        chunkStart, -corruptionMargin);\n\n    auto eventLessTime = [&](MIDIChannelEvent event, long long value) {\n        return (tickMode ? (long long)midi.GetEventAbsT(event) : midi.GetEventTime(event)) < value;\n    };\n    const auto itHi = std::lower_bound(events.begin(), events.end(), hi, eventLessTime);\n    const size_t hiIndex = (size_t)(itHi - events.begin());\n    if (hiIndex == 0)\n        return;\n\n    const auto& blockMax = tickMode ? maxEndTick : maxEndTime;\n    const auto& prefixMax = tickMode ? prefixEndTick : prefixEndTime;\n    if (blockMax.empty() || prefixMax.size() != blockMax.size())\n        return;\n\n    size_t block = (hiIndex - 1) / ImageBufferHugeBlockEvents;\n    if (block >= blockMax.size())\n        block = blockMax.size() - 1;\n\n    for (;;) {\n        if (prefixMax[block] < oldestUsefulEnd)\n            break;\n        if (blockMax[block] >= oldestUsefulEnd) {\n            const size_t begin = block * ImageBufferHugeBlockEvents;\n            const size_t end = (std::min)(hiIndex, begin + ImageBufferHugeBlockEvents);\n            for (size_t i = end; i != begin; ) {\n                --i;\n                const MIDIChannelEvent event = events[i];\n                if (midi.GetEventChannelEventType(event) != MIDI::NoteOn ||\n                    midi.GetEventParam2(event) <= 0 || !midi.EventHasSister(event))\n                    continue;\n                NoteData data = buildNote(event, chunkStart);\n                if (data.pos < (float)timeSpan &&\n                    data.pos + (std::max)(data.length, 0.0f) >= 0.0f)\n                    out.push_back(data);\n            }\n        }\n        if (block == 0)\n            break;\n        --block;\n    }\n}\n'''
p.write_text(s[:a] + new_helper + s[b:], encoding='utf-8')

rep('PianoFromAbove/GameState.cpp',
    '''            const long long imageBufferMaxLen = bTickMode ? m_llMaxNoteLenTicks : m_llMaxNoteLen; \\\n            ImageBufferCollectHugeLocal(m_vEvents, m_MIDI, chunkNotes, imageBufferChunk, T, E, \\\n                imageBufferMaxLen, bTickMode, \\\n                [&](MIDIChannelEvent imageBufferNote, long long imageBufferChunkStart) { \\\n                    return BuildChunkNoteData(imageBufferNote, imageBufferChunkStart); \\\n                }); \\\n''',
    '''            ImageBufferCollectHugeIndexed(m_vEvents, m_MIDI, chunkNotes, imageBufferChunk, T, E, bTickMode, \\\n                m_vImageBufferMaxEndTime, m_vImageBufferMaxEndTick, \\\n                m_vImageBufferPrefixEndTime, m_vImageBufferPrefixEndTick, \\\n                [&](MIDIChannelEvent imageBufferNote, long long imageBufferChunkStart) { \\\n                    return BuildChunkNoteData(imageBufferNote, imageBufferChunkStart); \\\n                }); \\\n''',
    'macro huge collector')

rep('PianoFromAbove/GameStateLegacy.inc',
    '''            m_llMaxNPS = 1;\n            vector<long long> noteTimes;\n            noteTimes.reserve(m_vEvents.size());\n            // Longest note (start -> sister start), both time domains; used by the image buffer to catch\n            // notes that begin before a chunk but overlap into it.\n            m_llMaxNoteLen = 0;\n            m_llMaxNoteLenTicks = 0;\n            for (size_t i = 0; i < m_vEvents.size(); i++)\n            {\n                if (m_MIDI.GetEventChannelEventType(m_vEvents[i]) == MIDI::NoteOn &&\n                    m_MIDI.GetEventParam2(m_vEvents[i]) > 0)\n                {\n                    noteTimes.push_back(m_MIDI.GetEventTime(m_vEvents[i]));\n                    if (m_MIDI.EventHasSister(m_vEvents[i]))\n                    {\n                        long long len = m_MIDI.GetEventLength(m_vEvents[i]);\n                        if (len > m_llMaxNoteLen)\n                            m_llMaxNoteLen = len;\n                        len = m_MIDI.GetEventAbsT(m_vEvents[m_MIDI.GetEventSisterIdx(m_vEvents[i])]) -\n                              m_MIDI.GetEventAbsT(m_vEvents[i]);\n                        if (len > m_llMaxNoteLenTicks)\n                            m_llMaxNoteLenTicks = len;\n                    }\n                }\n            }\n            if (!noteTimes.empty())\n            {\n                size_t left = 0;\n                for (size_t right = 0; right < noteTimes.size(); right++)\n                {\n                    while (noteTimes[right] - noteTimes[left] > 1000000)\n                        left++;\n                    long long curWindowNPS = (long long)(right - left + 1);\n                    if (curWindowNPS > m_llMaxNPS)\n                        m_llMaxNPS = curWindowNPS;\n                }\n            }''',
    '''            m_llMaxNPS = 1;\n            deque<long long> npsWindow;\n            const size_t imageBufferBlocks =\n                (m_vEvents.size() + ImageBufferHugeBlockEvents - 1) / ImageBufferHugeBlockEvents;\n            const long long imageBufferMinEnd = (std::numeric_limits<long long>::min)();\n            m_vImageBufferMaxEndTime.assign(imageBufferBlocks, imageBufferMinEnd);\n            m_vImageBufferMaxEndTick.assign(imageBufferBlocks, imageBufferMinEnd);\n            m_vImageBufferPrefixEndTime.resize(imageBufferBlocks);\n            m_vImageBufferPrefixEndTick.resize(imageBufferBlocks);\n            m_llMaxNoteLen = 0;\n            m_llMaxNoteLenTicks = 0;\n            for (size_t i = 0; i < m_vEvents.size(); i++)\n            {\n                const MIDIChannelEvent event = m_vEvents[i];\n                if (m_MIDI.GetEventChannelEventType(event) != MIDI::NoteOn ||\n                    m_MIDI.GetEventParam2(event) <= 0)\n                    continue;\n\n                const long long noteTime = m_MIDI.GetEventTime(event);\n                npsWindow.push_back(noteTime);\n                while (!npsWindow.empty() && noteTime - npsWindow.front() > 1000000)\n                    npsWindow.pop_front();\n                m_llMaxNPS = (std::max)(m_llMaxNPS, (long long)npsWindow.size());\n\n                if (!m_MIDI.EventHasSister(event))\n                    continue;\n                const MIDIChannelEvent sister =\n                    m_vEvents[m_MIDI.GetEventSisterIdx(event)];\n                const long long lengthTime = (std::max)(0LL, (long long)m_MIDI.GetEventLength(event));\n                const long long startTick = m_MIDI.GetEventAbsT(event);\n                const long long lengthTick = (std::max)(0LL,\n                    (long long)m_MIDI.GetEventAbsT(sister) - startTick);\n                m_llMaxNoteLen = (std::max)(m_llMaxNoteLen, lengthTime);\n                m_llMaxNoteLenTicks = (std::max)(m_llMaxNoteLenTicks, lengthTick);\n\n                const size_t block = i / ImageBufferHugeBlockEvents;\n                const long long endTime = ImageBufferOverlapWorstEnd(noteTime, lengthTime);\n                const long long endTick = ImageBufferOverlapWorstEnd(startTick, lengthTick);\n                m_vImageBufferMaxEndTime[block] =\n                    (std::max)(m_vImageBufferMaxEndTime[block], endTime);\n                m_vImageBufferMaxEndTick[block] =\n                    (std::max)(m_vImageBufferMaxEndTick[block], endTick);\n            }\n\n            long long prefixTime = imageBufferMinEnd;\n            long long prefixTick = imageBufferMinEnd;\n            for (size_t block = 0; block < imageBufferBlocks; ++block) {\n                prefixTime = (std::max)(prefixTime, m_vImageBufferMaxEndTime[block]);\n                prefixTick = (std::max)(prefixTick, m_vImageBufferMaxEndTick[block]);\n                m_vImageBufferPrefixEndTime[block] = prefixTime;\n                m_vImageBufferPrefixEndTick[block] = prefixTick;\n            }''',
    'loader NPS/index pass')

rep('PianoFromAbove/GameStateLegacy.inc',
    '''                ImageBufferCollectHugeLocal(m_vEvents, m_MIDI, chunkNotes, chunk, T, margin, maxLen, tickMode,\n                    [&](MIDIChannelEvent note, long long chunkStart) { return BuildChunkNoteData(note, chunkStart); });''',
    '''                ImageBufferCollectHugeIndexed(m_vEvents, m_MIDI, chunkNotes, chunk, T, margin, tickMode,\n                    m_vImageBufferMaxEndTime, m_vImageBufferMaxEndTick,\n                    m_vImageBufferPrefixEndTime, m_vImageBufferPrefixEndTick,\n                    [&](MIDIChannelEvent note, long long chunkStart) { return BuildChunkNoteData(note, chunkStart); });''',
    'strip huge collector')

rep('PianoFromAbove/GameStateLegacy.inc',
    '''    const long long maxLen = tickMode ? m_llMaxNoteLenTicks : m_llMaxNoteLen;\n    std::vector<NoteData> chunkNotes;''',
    '''    std::vector<NoteData> chunkNotes;''',
    'strip maxLen cleanup')

